// ============================================================================
//  formal/h_fifo.v — bounded formal harness for rtl/loom_fifo.v
//
//  Proves (BMC): after reset the FIFO is empty; the occupancy never exceeds
//  DEPTH; full/empty flags agree with the count.  Everything is 2-state SMT, so
//  "no X after reset" is expressed as the reset-state constants below.
//  Reset is generated by an internal counter (initial value 0), so no external
//  assumptions are needed.
// ============================================================================
`default_nettype none
module h_fifo(input wire clk);

  localparam DEPTH = 8;
  localparam AW = 3;
  localparam WIDTH = 8;

  reg [4:0] rst_cnt = 0;
  wire rst_n = (rst_cnt == 5'd4);
  always @(posedge clk) if (rst_cnt != 5'd4) rst_cnt <= rst_cnt + 5'd1;

  (* anyseq *) wire             wr_en;
  (* anyseq *) wire             rd_en;
  (* anyseq *) wire [WIDTH-1:0] wr_data;

  wire [WIDTH-1:0] rd_data;
  wire             full, empty;
  wire [AW:0]      count;

  loom_fifo #(.DEPTH(DEPTH), .AW(AW), .WIDTH(WIDTH)) dut (
      .clk(clk), .rst_n(rst_n),
      .wr_en(wr_en), .wr_data(wr_data), .full(full),
      .rd_en(rd_en), .rd_data(rd_data), .empty(empty),
      .count(count));

  reg post_reset = 1'b0;
  always @(posedge clk) post_reset <= rst_n;

  always @(posedge clk) if (post_reset) begin
    assert (count <= DEPTH);            // never overflows / underflows
    assert (full  == (count == DEPTH)); // flag/count consistency
    assert (empty == (count == 0));
  end

  // reset completeness: the first cycle after rst_n release sees empty FIFO
  reg first_post = 1'b1;
  always @(posedge clk) begin
    if (!rst_n) first_post <= 1'b1;
    else if (first_post) begin
      assert (count == 0);
      assert (empty);
      assert (!full);
      first_post <= 1'b0;
    end
  end

endmodule
`default_nettype wire
